import java.util.*;

public class Solution {
    private static int[] para, prox, cabeca;
    private static long[] cap;
    private static long fluxo;

    // Lista de arestas em arrays: a aresta i e sua reversa i ^ 1 ficam lado a lado.
    private static void rodar(int n, int[][] arestas, int s, int t) {
        int m = arestas.length * 2;
        para = new int[m];
        prox = new int[m];
        cap = new long[m];
        cabeca = new int[n];
        Arrays.fill(cabeca, -1);
        int k = 0;
        for (int[] e : arestas) {
            para[k] = e[1]; cap[k] = e[2]; prox[k] = cabeca[e[0]]; cabeca[e[0]] = k++;
            para[k] = e[0]; cap[k] = 0;    prox[k] = cabeca[e[1]]; cabeca[e[1]] = k++;
        }
        fluxo = 0;
        int[] veio = new int[n];
        while (true) {
            Arrays.fill(veio, -1);
            ArrayDeque<Integer> fila = new ArrayDeque<>();
            fila.add(s);
            veio[s] = -2;
            while (!fila.isEmpty() && veio[t] == -1) {
                int u = fila.poll();
                for (int e = cabeca[u]; e != -1; e = prox[e]) {
                    if (cap[e] > 0 && veio[para[e]] == -1) {
                        veio[para[e]] = e;
                        fila.add(para[e]);
                    }
                }
            }
            if (veio[t] == -1) return;
            long gargalo = Long.MAX_VALUE;
            for (int v = t; v != s; v = para[veio[v] ^ 1]) gargalo = Math.min(gargalo, cap[veio[v]]);
            for (int v = t; v != s; v = para[veio[v] ^ 1]) {
                cap[veio[v]] -= gargalo;
                cap[veio[v] ^ 1] += gargalo;
            }
            fluxo += gargalo;
        }
    }

    static long fluxoMaximo(int n, int[][] arestas, int s, int t) {
        rodar(n, arestas, s, t);
        return fluxo;
    }

    static boolean[] ladoDaFonte(int n, int[][] arestas, int s, int t) {
        rodar(n, arestas, s, t);
        boolean[] lado = new boolean[n];
        ArrayDeque<Integer> fila = new ArrayDeque<>();
        fila.add(s);
        lado[s] = true;
        while (!fila.isEmpty()) {
            int u = fila.poll();
            for (int e = cabeca[u]; e != -1; e = prox[e]) {
                if (cap[e] > 0 && !lado[para[e]]) {
                    lado[para[e]] = true;
                    fila.add(para[e]);
                }
            }
        }
        return lado;
    }
}

