import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static final int[][] G = {{0, 1, 16}, {0, 2, 13}, {1, 2, 10}, {2, 1, 4}, {1, 3, 12}, {3, 2, 9}, {2, 4, 14}, {4, 3, 7}, {3, 5, 20}, {4, 5, 4}};

    private static long corte(int[][] e, boolean[] lado) {
        long c = 0;
        for (int[] a : e) if (lado[a[0]] && !lado[a[1]]) c += a[2];
        return c;
    }

    @Test void classico() {
        assertEquals(23, Solution.fluxoMaximo(6, G, 0, 5));
        boolean[] lado = Solution.ladoDaFonte(6, G, 0, 5);
        assertTrue(lado[0]);
        assertFalse(lado[5]);
        assertEquals(23, corte(G, lado));
    }

    @Test void precisaDaReversa() {
        // Sem desfazer fluxo pela aresta reversa, um caminho guloso ruim trava em 1.
        int[][] e = {{0, 1, 1}, {0, 2, 1}, {1, 2, 1}, {1, 3, 1}, {2, 3, 1}};
        assertEquals(2, Solution.fluxoMaximo(4, e, 0, 3));
    }

    @Test void desconectadoEParalelas() {
        assertEquals(0, Solution.fluxoMaximo(3, new int[][]{{0, 1, 5}}, 0, 2));
        assertEquals(7, Solution.fluxoMaximo(2, new int[][]{{0, 1, 3}, {0, 1, 4}}, 0, 1));
    }

    @Test void aleatorioCorteIgualFluxo() {
        var rnd = new Random(14);
        for (int t = 0; t < 30; t++) {
            int n = 30;
            int[][] e = new int[200][];
            for (int i = 0; i < e.length; i++) e[i] = new int[]{rnd.nextInt(n), rnd.nextInt(n), rnd.nextInt(100)};
            long f = Solution.fluxoMaximo(n, e, 0, n - 1);
            assertEquals(f, corte(e, Solution.ladoDaFonte(n, e, 0, n - 1)));
        }
    }
}
